pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract DutchAuction is ReentrancyGuard {
    IERC721 public nft;
    uint256 public nftId;

    uint256 public constant DURATION = 3 days;
    uint256 public startPrice;
    uint256 public discountRate;
    uint256 public startTime;
    address public seller;

    constructor(address _nft, uint256 _nftId, uint256 _startPrice, uint256 _discountRate) {
        nft = IERC721(_nft);
        nftId = _nftId;
        startPrice = _startPrice;
        discountRate = _discountRate;
        startTime = block.timestamp;
        seller = msg.sender;
    }

    function getPrice() public view returns (uint256) {
        uint256 elapsed = block.timestamp - startTime;
        uint256 discount = discountRate * elapsed;
        if (discount >= startPrice) return 0;
        return startPrice - discount;
    }

    function buy() external payable nonReentrant {
        require(block.timestamp < startTime + DURATION, "Auction ended");
        uint256 price = getPrice();
        require(msg.value >= price, "Insufficient ETH");
        nft.transferFrom(seller, msg.sender, nftId);
        uint256 refund = msg.value - price;
        if (refund > 0) payable(msg.sender).transfer(refund);
    }
}

// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

contract MultiSigWallet {
    address[] public owners;
    mapping(address => bool) public isOwner;
    uint256 public required;

    struct Transaction { address to; uint256 value; bytes data; bool executed; uint256 confirmations; }
    mapping(uint256 => Transaction) public transactions;
    mapping(uint256 => mapping(address => bool)) public confirmed;
    uint256 public txCount;

    event Submit(uint256 indexed txId);
    event Confirm(address indexed sender, uint256 indexed txId);
    event Execute(uint256 indexed txId);

    constructor(address[] memory _owners, uint256 _required) {
        require(_owners.length > 0 && _required > 0 && _required <= _owners.length);
        for (uint256 i = 0; i < _owners.length; i++) {
            isOwner[_owners[i]] = true;
        }
        owners = _owners;
        required = _required;
    }

    function submit(address to, uint256 value, bytes memory data) external {
        require(isOwner[msg.sender], "Not owner");
        transactions[txCount] = Transaction(to, value, data, false, 0);
        emit Submit(txCount++);
    }

    function confirm(uint256 txId) external {
        require(isOwner[msg.sender] && !confirmed[txId][msg.sender]);
        confirmed[txId][msg.sender] = true;
        transactions[txId].confirmations++;
        emit Confirm(msg.sender, txId);
    }

    function execute(uint256 txId) external {
        Transaction storage t = transactions[txId];
        require(!t.executed && t.confirmations >= required, "Not enough confirmations");
        t.executed = true;
        (bool ok,) = t.to.call{value: t.value}(t.data);
        require(ok, "Tx failed");
        emit Execute(txId);
    }
}

# @version ^0.3.10

beneficiary: public(address)
auctionEndTime: public(uint256)
highestBidder: public(address)
highestBid: public(uint256)
ended: public(bool)

@external
def __init__(_beneficiary: address, _duration: uint256):
    self.beneficiary = _beneficiary
    self.auctionEndTime = block.timestamp + _duration

@external
@payable
def bid():
    assert block.timestamp < self.auctionEndTime, "Auction ended"
    assert msg.value > self.highestBid, "Bid too low"
    if self.highestBid > 0:
        send(self.highestBidder, self.highestBid)
    self.highestBidder = msg.sender
    self.highestBid = msg.value

@external
def endAuction():
    assert block.timestamp >= self.auctionEndTime, "Not yet ended"
    assert not self.ended, "Already ended"
    self.ended = True
    send(self.beneficiary, self.highestBid)

use cosmwasm_std::{entry_point, DepsMut, Env, MessageInfo, Response, StdError};
use serde::{Deserialize, Serialize};

#[derive(Serialize, Deserialize, Clone)]
pub struct State {
    pub count: i32,
    pub owner: String,
}

#[derive(Serialize, Deserialize, Clone)]
#[serde(rename_all = "snake_case")]
pub enum ExecuteMsg {
    Increment {},
    Reset { count: i32 },
}

#[entry_point]
pub fn execute(
    deps: DepsMut,
    _env: Env,
    info: MessageInfo,
    msg: ExecuteMsg,
) -> Result<Response, StdError> {
    match msg {
        ExecuteMsg::Increment {} => {
            // load state, increment, save
            Ok(Response::new()
                .add_attribute("action", "increment")
                .add_attribute("sender", info.sender.to_string()))
        }
        ExecuteMsg::Reset { count } => {
            Ok(Response::new()
                .add_attribute("action", "reset")
                .add_attribute("count", count.to_string()))
        }
    }
}

