const COUNTER: Symbol = symbol_short!("COUNTER");

#[contract]
pub struct HelloContract;

#[contractimpl]
impl HelloContract {
    pub fn increment(env: Env) -> i32 {
        let mut count: i32 = env.storage().instance().get(&COUNTER).unwrap_or(0);
        count += 1;
        env.storage().instance().set(&COUNTER, &count);
        count
    }
}

