pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

contract TokenVesting is ReentrancyGuard {
    IERC20 public token;
    struct VestingSchedule {
        address beneficiary;
        uint256 totalAmount;
        uint256 released;
        uint256 start;
        uint256 duration;
        uint256 cliff;
    }

    mapping(bytes32 => VestingSchedule) public schedules;

    constructor(address _token) {
        token = IERC20(_token);
    }

    function createSchedule(
        address beneficiary,
        uint256 amount,
        uint256 start,
        uint256 duration,
        uint256 cliff
    ) external returns (bytes32 vestingId) {
        vestingId = keccak256(abi.encodePacked(beneficiary, start, duration, amount));
        schedules[vestingId] = VestingSchedule(beneficiary, amount, 0, start, duration, cliff);
        token.transferFrom(msg.sender, address(this), amount);
    }

    function vestedAmount(bytes32 vestingId) public view returns (uint256) {
        VestingSchedule storage s = schedules[vestingId];
        if (block.timestamp < s.start + s.cliff) return 0;
        if (block.timestamp >= s.start + s.duration) return s.totalAmount;
        return (s.totalAmount * (block.timestamp - s.start)) / s.duration;
    }

    function release(bytes32 vestingId) external nonReentrant {
        VestingSchedule storage s = schedules[vestingId];
        uint256 releasable = vestedAmount(vestingId) - s.released;
        require(releasable > 0, "Nothing to release");
        s.released += releasable;
        token.transfer(s.beneficiary, releasable);
    }
}

import hashlib

def keccak256(data: bytes) -> bytes:
    from eth_hash.auto import keccak
    return keccak(data)

class MerkleTree:
    def __init__(self, leaves: list[bytes]):
        self.leaves = [keccak256(l) for l in leaves]
        self.layers = [self.leaves]
        self._build()

    def _build(self):
        layer = self.leaves[:]
        while len(layer) > 1:
            if len(layer) % 2 == 1:
                layer.append(layer[-1])
            next_layer = []
            for i in range(0, len(layer), 2):
                combined = keccak256(layer[i] + layer[i+1])
                next_layer.append(combined)
            self.layers.append(next_layer)
            layer = next_layer

    @property
    def root(self) -> bytes:
        return self.layers[-1][0]

    def get_proof(self, index: int) -> list[bytes]:
        proof = []
        for layer in self.layers[:-1]:
            sibling_index = index ^ 1
            proof.append(layer[sibling_index])
            index //= 2
        return proof

    @staticmethod
    def verify(leaf: bytes, proof: list[bytes], root: bytes) -> bool:
        computed = leaf
        for sibling in proof:
            computed = keccak256(computed + sibling)
        return computed == root

# Usage
addresses = [b"0x1234...", b"0x5678...", b"0xabcd..."]
tree = MerkleTree(addresses)
proof = tree.get_proof(0)
print("Valid:", MerkleTree.verify(tree.leaves[0], proof, tree.root))

